local function _load()
    local _full = table.concat(_d)
    local _res = {}
    local b_xor = (bit32 and bit32.bxor) or function(a, b)
        local r, m = 0, 1
        while a > 0 or b > 0 do
            if a % 2 ~= b % 2 then r = r + m end
            a, b, m = math.floor(a / 2), math.floor(b / 2), m * 2
        end
        return r
    end
    
    local i = 1
    for b in _full:gmatch("(%d+)") do
        _res[i] = string.char(b_xor(tonumber(b), _k))
        i = i + 1
    end
    return table.concat(_res)
end

print("Kuma Hub: Decrypting...")
local success, result = pcall(function()
    local code = _load()
    local func, err = loadstring(code)
    if not func then 
        warn("Syntax Error in Code: " .. tostring(err))
        return 
    end
    print("Kuma Hub: Executing...")
    return func()
end)

if not success then
    warn("KUMA HUB FATAL ERROR: " .. tostring(result))
end

